/* @autogenerated */
package net.civeira.phylax.feature.observe.issue;

import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

class HyperLogLogUnitTest {

  @Test
  @DisplayName("Small counts are exact; large ones within a few per cent")
  void estimate() {
    HyperLogLog small = new HyperLogLog();
    for (int i = 0; i < 20; i++) {
      small.add("user-" + (i % 7));
    }
    Assertions.assertEquals(7, small.estimate());
    HyperLogLog large = new HyperLogLog();
    for (int i = 0; i < 50_000; i++) {
      large.add("user-" + i);
    }
    Assertions.assertEquals(50_000, large.estimate(), 50_000 * 0.08);
  }

  @Test
  @DisplayName("Merging two batches does not count twice; the sketch survives base64")
  void merge() {
    HyperLogLog a = new HyperLogLog();
    HyperLogLog b = new HyperLogLog();
    for (int i = 0; i < 300; i++) {
      a.add("u" + i);
      b.add("u" + (i + 150));
    }
    HyperLogLog stored = HyperLogLog.fromBase64(a.toBase64());
    Assertions.assertEquals(450, stored.merge(b).estimate(), 450 * 0.08);
    Assertions.assertEquals(0, HyperLogLog.fromBase64("not base64").estimate());
  }

  @Test
  @DisplayName("The context takes the user, else the session; pseudonyms are stable and not the id")
  void contextAndPseudonym() {
    EventContext anonymous = EventContext.of(Map.of("security.actor.uid", "", "session.id", "s-1"));
    Assertions.assertEquals("session:s-1", anonymous.who());
    Assertions.assertEquals("user:u-1", EventContext.of(Map.of("enduser.id", "u-1")).who());
    Pseudonym pseudonym = new Pseudonym("salt");
    Assertions.assertEquals(pseudonym.of("who", "user:u-1"), pseudonym.of("who", "user:u-1"));
    Assertions.assertNotEquals(pseudonym.of("who", "user:u-1"),
        new Pseudonym("other").of("who", "user:u-1"));
    Assertions.assertFalse(pseudonym.of("who", "user:u-1").contains("u-1"));
    Assertions.assertNull(pseudonym.of("who", null));
  }
}
